package local.tvmorph.tv;
import android.content.*;import android.content.pm.ProviderInfo;import android.net.Uri;import android.os.ParcelFileDescriptor;import java.io.*;
public final class UpdaterCheck{
 public static void run(Context c)throws Exception{TvUpdater.source("http://10.0.0.64:8788/tv-morph.apk");String[] bad={"http://8.8.8.8:8788/tv-morph.apk","http://127.0.0.1:8788/tv-morph.apk","http://10.0.0.64:80/tv-morph.apk","https://10.0.0.64:8788/tv-morph.apk","http://10.0.0.64:8788/private","http://10.0.0.64:8788/tv-morph.apk?file=private","http://user@10.0.0.64:8788/tv-morph.apk"};for(String s:bad){boolean rejected=false;try{TvUpdater.source(s);}catch(Exception e){rejected=true;}if(!rejected)throw new Exception("Unsafe update source accepted");}TvUpdater.verify(c,new File(c.getApplicationInfo().sourceDir));File invalid=new File(c.getCacheDir(),"invalid.apk");try(FileOutputStream out=new FileOutputStream(invalid)){out.write(new byte[]{1,2,3});}boolean rejected=false;try{TvUpdater.verify(c,invalid);}catch(Exception e){rejected=true;}invalid.delete();if(!rejected)throw new Exception("Invalid APK accepted");File verified=new File(c.getCacheDir(),"verified-update.apk");try(FileOutputStream out=new FileOutputStream(verified)){out.write(new byte[]{4,5,6});}UpdateProvider provider=new UpdateProvider();ProviderInfo info=new ProviderInfo();info.authority=c.getPackageName()+".updates";provider.attachInfo(c,info);Uri uri=Uri.parse("content://"+info.authority+"/tv-morph.apk");try(ParcelFileDescriptor fd=provider.openFile(uri,"r")){if(fd.getStatSize()!=3)throw new Exception("Provider wrong file");}for(String mode:new String[]{"w","rw"}){rejected=false;try{provider.openFile(uri,mode);}catch(Exception e){rejected=true;}if(!rejected)throw new Exception("Writable update provider");}rejected=false;try{provider.openFile(Uri.parse("content://"+info.authority+"/../private"),"r");}catch(Exception e){rejected=true;}verified.delete();if(!rejected)throw new Exception("Provider path escaped");}
}